data.script:
const t=app.lightTheme;
if(!(t instanceof Theme)||t.type!=='file')throw Error('Select the neutral light file theme first');
const found=Theme.find('file',t.name);
if(!found||found.uuid!==t.uuid)throw Error('Configured/catalog identity mismatch');
const payload=JSON.parse(decodeURIComponent(t.installURL.split('data=')[1]));
if(payload.id.toUpperCase()!==t.uuid.toUpperCase())throw Error('Portable source identity mismatch');
app.displayInfoMessage(t.uuid+'; source '+payload.background);
